INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('e73d75fa-1ebe-40a5-9dfe-c519b5b7b31f','كيف تواجه نادك أزمة إغلاق المضيقين؟','ضيفنا في هذه الحلقة سليمان بن عبدالعزيز التويجري، الرئيس التنفيذي لشركة نادك.تسلَّم التويجري قيادة الشركة حين كانت تسجل خسائر بنحو 285 مليون ريال، وأعادها إلى الربحية حتى تجاوزت أرباحها الصافية 500 مليون ريال.ويرى التويجري أن كفاءة التصنيع تتطلب حضور القائد في الميدان، حيث تتضح له تفاصيل لا تكشفها المكاتب المكيفة، وأن وجوده بين الموظفين يعزز ارتباطهم بالشركة.وفي إدارة الأزمات، يكشف كيف اتخذ قرارًا بحجز أكثر من مليار ريال لتأمين مخزون الأعلاف لعام كامل، تحسبًا لإغلاق مضيق هرمز وتداعياته على الإمد','https://api.hosting.thmanyah.com/episodeAudioFile/9742/file.mp3',7019,'2026-11-22T11:00:17.000Z'::timestamptz,22001);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('e73d75fa-1ebe-40a5-9dfe-c519b5b7b31f','الذكاء الاصطناعي بين الوهم والواقع','وسط موجة المبالغة والترويج المفرط للذكاء الاصطناعي من الشركات وصناع المحتوى، تأتي هذه الحلقة من منطق واضح موجّه لكل أحد يريد معرفة الذكاء الاصطناعي، إلى أين وصل؟ وكيف نستفيد منه اليوم؟ضيف هذه الحلقة في مازن ميلباري، حامل لشهادة الدكتوراة في الذكاء الاصطناعي، ومهتم بالقطاع منذ صغره. نتحدث عن الاستخدامات العملية لتقنيات الذكاء الاصطناعي، التي تفيد الشركات الناشئة والكبيرة، وتحديات التعامل العشوائي مع بعضها مثل «شات جي بي تي»، ورفع الملفات الحساسة عليه، وكيف يؤدي إلى تسرّب البيانات دون وعينا!هل فعل','https://api.hosting.thmanyah.com/episodeAudioFile/6689/file.mp3',7503,'2025-11-17T03:00:21.000Z'::timestamptz,28568);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('e73d75fa-1ebe-40a5-9dfe-c519b5b7b31f','كيف تعمل شركات تصنيع المكياج','برزت في السنوات الأخيرة علامات تجارية في عالم التجميل والزينة، من بينها شركة أستيري السعودية. للحديث عنها أكثر استضفنا في هذه الحلقة مؤسسة الشركة سارة الراشد.تقول سارة إن ما يميّز أستيري هو تصنيعها لمنتجات تشبهنا وتناسب بيئنا، فهي تتحمل حرارة الجو والجفاف، وتلائم الملامح العربية ولون بشرتهم. لكن لكي يُعتمد المنتج لا بد أن يمر بمرحلة تصنيع وتطوير طويلة، قد تستغرق أحيانًا فوق السنتين للمنتج الواحد!فما رحلة تطوير المنتج؟ ماذا يعني أن يكون المنتج نظيفًا؟ وكيف يختلف عن المنتجات الطبيعية والعضوية؟ كما','https://api.hosting.thmanyah.com/episodeAudioFile/6663/file.mp3',4781,'2025-11-10T09:00:36.000Z'::timestamptz,14659);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('e73d75fa-1ebe-40a5-9dfe-c519b5b7b31f','أين الفرص الاستثمارية في قطاع الصناعات العسكرية','نستضيف في هذه الحلقة بدر المصيبيح، المدير العام لشركة الوطنية المالية، شركة استثمارية سعودية تعمل على تمويل قطاعات استراتيجية برزت مع رؤية 2030، مثل قطاع الصناعات العسكرية والدفاعية.&nbsp;تماشيًا مع الرؤية، قرر بدر وشركاؤه الاستثمار في قطاع الصناعات العسكرية رغم خلفيته البعيدة عنه. يتحدث في هذه الحلقة عن كيف يعمل هذا القطاع ضمن شركة خاصة وليست حكومية كما المعتاد.يرى بدر أن قطاع الصناعات العسكرية والدفاعية ليس حساسًا أبدًا، إنما يتطلب مواصفات معينة للتعامل معه. فكيف يدخل المستثمرون وروّاد الأعمال','https://api.hosting.thmanyah.com/episodeAudioFile/6626/file.mp3',8416,'2025-11-04T03:00:47.000Z'::timestamptz,23849);

