INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('75c6ca3b-5e0d-4564-b97d-e86a1eaa31ac','الستاند اب كوميدي بين الفن و التيك توك | بودكاست شنو الكوميديا','أربعة كوميديين، ليلة على المسرح، وفي اليوم التالي… كل شخص لديه رواية مختلفة عمّا حدث! 🎤😂في هذه الحلقة من بودكاست شنو الكوميديا، يجتمع بدر صالح مع مهند مجيد ومحمد طارق وتشارلز حبيليني بعد مشاركتهم في عرض &quot;Next Up — اللي بعده&quot;، لاستعادة مواقف تلك الليلة والحديث عن الكوميديا من داخل الكواليس. كيف عاش كل واحد منهم التجربة؟ وماذا حدث عندما اجتمعوا على المسرح وبدأوا التفاعل مع الجمهور؟ومن ذكريات العرض، ينتقل الحديث إلى سؤال يبدو بسيطًا: ما هو الستاند أب كوميدي فعلًا؟ هل هو فن أم مهارة؟ وكي','https://www.buzzsprout.com/2532512/episodes/19901309-.mp3',5256,'2026-10-02T18:00:00.000Z'::timestamptz,37155);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('75c6ca3b-5e0d-4564-b97d-e86a1eaa31ac','الكوميديا السوداء، البشير شو والبدايات | بودكاست شنو شنو الكوميديا مع احمد البشير','هل الدارك كوميدي مجرد أسلوب للضحك، أم مساحة حقيقية لكسر التابوهات؟ وأين يقف الخط الفاصل بين الجرأة والمخاطرة؟في هذه الحلقة من بودكاست شنو الكوميديا، يستضيف بدر صالح ومؤمن أفندي الكوميديان العراقي المخضرم أحمد البشير في نقاش صريح حول الدارك كوميدي، حضوره في الساحة العربية، وكيف يُفهم ويُقدَّم في مجتمعات مختلفة، خصوصًا في العراق.ما هو تعريف الدارك كوميدي بالنسبة لأحمد البشير؟ وما أنواعه؟ وأي نوع يفضله؟وهل فعلاً يمكن للكوميديان أن يتجاوز الخطوط الحمراء على المسرح؟ وماذا يتعلّم من هذه التجارب مع الو','https://www.buzzsprout.com/2532512/episodes/19108295-.mp3',3464,'2026-05-01T18:00:00.000Z'::timestamptz,37172);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('75c6ca3b-5e0d-4564-b97d-e86a1eaa31ac','كيف تصنع الكوميديان؟ | بودكاست شنو الكوميديا مع بدر صالح ومؤمن أفندي','كيف يُصنع الكوميديان؟وهل الضحك موهبة فقط، أم مهارة تُبنى خطوة خطوة؟في هذه الحلقة من بودكاست شنو الكوميديا، يجلس بدر صالح ومؤمن أفندي في نقاش مباشر عن الكوميديان نفسه:من هو؟ وكيف يختلف الستاند أب كوميدي عن مقدم البرامج؟ وما الذي يجعل شخصًا ينجح على المسرح بينما يفشل آخر؟الحلقة تغوص في أساسيات صناعة الكوميدي، من: • بناء شخصية الكوميديان • كتابة النكتة وتحويل الفكرة إلى ضحك • الأداء على المسرح • وأهمية الـ Delivery والقبول والكاريزماكما يناقش بدر ومؤمن كيف تطلع بذبات تضحك فعلًا، وأفكار عملية تساعد ','https://www.buzzsprout.com/2532512/episodes/18679419-.mp3',3519,'2026-02-14T00:00:00.000Z'::timestamptz,26451);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('75c6ca3b-5e0d-4564-b97d-e86a1eaa31ac','بودكاست شنو الكوميديا مع فهد سال | بدر صالح ومؤمن أفندي','في هذه الحلقة من بودكاست شنو الكوميديا؟ يستضيف بدر ضالح ومؤمن افندي الكوميديان فهد سال و يسألون: كيف تبدأ فكرة بسيطة وتتحول إلى ظاهرة على الإنترنت؟نحكي مع فهد سال عن بداياته، فكرة البردي، وكيف صار وجهه مادة للميمز المنتشرة، ورأيه بثقافة الميمز في العالم العربي.نغوص في رحلته مع الستاند أب كوميدي (Stand-up Comedy)، انتقاله إلى الغيمنغ (Gaming)، الألعاب اللي أثرت فيه، ومتى قرر ياخذ هذا المسار بجدية.كما نتكلم عن الأنمي (Anime)، رأيه في ون بيس (One Piece) كأفضل صيغة قصصية، التمثيل الصوتي (Voice Actin','https://www.buzzsprout.com/2532512/episodes/18591400-.mp3',3383,'2026-01-29T17:00:00.000Z'::timestamptz,47581);

