INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('a2608156-e4f2-4f7b-a319-f7e9b2bdc36a','الحلقة السابعة من #الموسم2: مهارة إدارة الفاميلي بيزنس - باسم محسن','نستضيف باسم محسن، مؤسس مجموعة B.M.G المالكة لعدد من المدارس داخل وخارج مصر. وبيحكيلنا عن رحلته في إدارة الفاميلي بيزنس وازاي قدر يطوّرها من مشروع عائلي إلى مجموعة تعليمية بتقدم قيمة حقيقية. بنتعرف كمان على كواليس بيزنس المدارس، والتحديات اللي بيواجهها القطاع، وإزاي يقدر يحافظ على التوازن بين تحقيق الربح وبين تقديم رسالة تعليمية محترمة وذات أثر. نناقش معاه مفهوم التطوير الإداري داخل المؤسسات العائلية، أهمية الانتقال من الإدارة التقليدية للحوكمة الاحترافية، وإزاي بيتم بناء مدارس ناجحة تجمع بين الج','https://content.rss.com/episodes/313887/2328206/maharatpodcast/2025_11_14_16_18_37_7766ac8f-1b8c-449e-927e-3bed9cfa3d69.mp3',5289,'2025-11-14T16:18:52.000Z'::timestamptz,50256);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('a2608156-e4f2-4f7b-a319-f7e9b2bdc36a','الحلقة السادسة من #الموسم2: مهارة إدارة البشر في "مالتي ناشيونالز" - خالد الدسوقي','في الحلقة السادسة من الموسم الثاني من بودكاست مهارات مع نديم بركات، نستضيف خالد الدسوقي للحديث عن خبرته الواسعة في عالم الشركات متعددة الجنسيات (المالتي ناشيونالز). بيشاركنا خالد رحلته المهنية وإزاي اكتسب مهارة إدارة البشر والفرق في بيئات عمل تتسم بالتنوع الثقافي والجغرافي. كمان بنتناول أهمية الـ Management Consultancy وكيفية تطبيقها، مع تحليل الفروقات الدقيقة بين الثقافات الأمريكية واليابانية والألمانية في البيزنس وتأثير هذه الاختلافات على القيادة والاستراتيجيات العالمية. البودكاست فكرة وتقديم ','https://content.rss.com/episodes/313887/2302027/maharatpodcast/2025_10_31_17_46_28_31392240-043f-4058-b818-de122f86e6d9.mp3',5374,'2025-10-31T17:48:18.000Z'::timestamptz,10506);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('a2608156-e4f2-4f7b-a319-f7e9b2bdc36a','الحلقة الخامسة من #الموسم2: مهارة التواصل - عمر المنير','في الحلقة الخامسة من الموسم التاني من بودكاست مهارات مع نديم بركات، بنستضيف عمر المنير، المؤسس والرئيس التنفيذي لشركة Sigma Fit. حوار عن فن ومهارة التواصل، إزاي بيختلف تواصلك مع شخص عن تواصلك مع مجموعة، وإزاي التطور السريع في الذكاء الاصطناعي ممكن يغيّر شكل التواصل اللي إحنا عارفينه. هتعرف ليه التواصل هو سر قوة الشعوب، وليه الأعداء أول حاجة بيحاولوا يهدّوها دايمًا هي شبكة التواصل ومقوماتها.Maharat Podcast, created and hosted by Nadeem Barakat.Produced by Maddar.Beverage Sponsor: Pop Soda','https://content.rss.com/episodes/313887/2275988/maharatpodcast/2025_10_17_11_57_13_f11a5b52-63a5-4ff1-8435-17294a78c51d.mp3',5725,'2025-10-17T14:50:07.000Z'::timestamptz,41428);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('a2608156-e4f2-4f7b-a319-f7e9b2bdc36a','الحلقة الرابعة من #الموسم2: مهارة رائد الأعمال - محمد جاويش','في رابع حلقة من الموسم الثاني من بودكاست مهارات مع نديم بركات، نستضيف محمد جاويش؛ المؤسس والرئيس التنفيذي لـ "آي سكوول" للحديث عن رحلته في ريادة الأعمال في مجال التعليم، تجربته في السوق المصري، ورأيه في التوسُّع لأسواق خارجية. البودكاست فكرة وتقديم نديم بركات، ومن إعداد وإنتاج مدار. Maharat Podcast, created and hosted by Nadeem Barakat. Produced by Maddar. Beverage Sponsor: Pop Soda','https://content.rss.com/episodes/313887/2251219/maharatpodcast/2025_10_03_12_30_18_31044ed4-1b8a-4d4f-9a8a-77e707a47e94.mp3',6694,'2025-10-03T14:50:09.000Z'::timestamptz,50688);

