INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('44a82897-157b-4d49-91c0-e0ed0be685d8','#84 أحب أعترف بالفشل 🤷🏻‍♂️ | عبدالله الربيعة (أبو ربيعة)','سولفنا مع أبو ربيعة عن دخوله إلى عالم البزنس، وعن كمال الأجسام والبطولات، وبطولة الكمال لله، وتكلمنا عن مدى تأثير المدرب على اللاعب، وعن نادي شبوف، وعن البيف بروتين، وإبر التنحيف، وسوينا فقرة تحدي اللياقة، وأنهينا الحلقة برسالة يصير خير.','https://www.buzzsprout.com/2196707/episodes/20137689-84.mp3',5865,'2026-11-18T12:00:00.000Z'::timestamptz,22270);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('44a82897-157b-4d49-91c0-e0ed0be685d8','#83 بغيت أنطرد من البيت بسبب الذكاء الإصطناعي 🤖 | طرفة الشريف','ضيفة الحلقةطرفة الشريفممثلة وصانعة محتوى سعودية، عرفها الجمهور بشخصية &quot;نوف&quot; في مسلسل شباب البومب، ثم لفتت الأنظار بدور &quot;عطوى&quot; في مسلسل شارع الأعشى الذي نال أداؤها فيه إشادة واسعة، تُعد من أبرز الوجوه الشابة الصاعدة في الدراما السعودية.سولفنا مع طرفة عن شخصيتها وهي صغيرة وكيف بدأت التمثيل وعن تجاربها وقصصها في الأعمال اللي مثلت فيها، وعن تجربة الإعلانات والأغاني وسولفنا عن رغبتها في دخول تمثيل الأكشن، ولعبنا معها إنسان حيوان جماد وأنهينا الحلقة برسالة يصير خير','https://www.buzzsprout.com/2196707/episodes/20108193-83.mp3',5362,'2026-11-11T12:00:00.000Z'::timestamptz,8635);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('44a82897-157b-4d49-91c0-e0ed0be685d8','#82 حورنيات هو طاش ما طاش مسموع 📼 | حامد الضبعان','ضيف الحلقةحامد الضبعانمنشد وفنان سعودي اشتهر بسلسلة ألبومات &quot;حورنيات&quot; التي صدرت منها عدة أجزاء، وصار من أبرز الأسماء في الإنشاد والشيلات. شارك في التمثيل في مسلسلي &quot;شقتكو&quot; و&quot;صباح الليل&quot; بأجزائه.سولفنا مع حامد الضبعان عن بداية دخوله لمجال الإنشاد وردة فعل والده ومن حوله، وعن فترة انقطاعه وعودته، وعن تجربته في التمثيل والصعوبات التي يواجهها، وعن عودته في إحياء الحفلات، وعن رأيه في بعض المواضيع، وسوينا معه فقرة كلمة ولحن وأنهينا الحلقة برسالة يصير خير','https://www.buzzsprout.com/2196707/episodes/20065101-82.mp3',7395,'2026-11-04T12:00:00.000Z'::timestamptz,4451);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('44a82897-157b-4d49-91c0-e0ed0be685d8','#81 هدفي أفوز بجائزة أفضل صانع محتوى 🏆 | محمد أودين','ضيف الحلقةمحمد أودنصانع محتوى سعودي وعضو في فريق Team Falcons، يجمع في محتواه بين الأنمي والألعاب، وعُرف بشخصيته الواثقة وأسلوبه الكوميدي، ومن أشهر أعماله تحدي الكنبة وبنك الأنمي.سولفنا مع أودين عن المشاريع اللي ما شافت النور، وعن الألعاب القصصية وأفضل 3 ألعاب قصصية بالنسبة له، وعن المقارنة بين الكمبيوتر والبلايستيشن وقصة دخوله لفالكونز، وعن صناعة المحتوى وجوائز صناع المحتوى وعن السلاسل اللي يقدمها، وعن بطولة الكمال لل','https://www.buzzsprout.com/2196707/episodes/20032892-81.mp3',7793,'2026-10-28T12:00:00.000Z'::timestamptz,38435);

