INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('a9a80d26-9ea0-4559-ae27-182c013bbd2a','عندك مناعة نفسية؟','ارتجال بودكاست نسولف عن مواضيع مختلفة. تبينا نسولف عن موضوع يهمك ولا عندك ملاحظة ودك تشاركها تواصل معنا على : ertigalbodcast@gmail.com Twitter: https://twitter.com/ErtigalPodcast Background Music: https://www.youtube.com/watch?v=b8F9hP6n1_Y الكتاب اللي ذكره ياسر The Resilience Factor: 7 Keys to Finding Your Inner Strength and Overcoming Life''s Hurdles https://www.amazon.com/dp/0767911911/ref=cm_sw_r_wa_apa_FvRIBb63PPVP2 كورسات بنسلفانيا على كورسيرا https://www.coursera.org/specializations/positi','https://feeds.soundcloud.com/stream/496701828-user-318573365-ppjkmu4ttaav.mp3',2888,'2018-09-07T18:21:01.000Z'::timestamptz,15747);
