INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('9c3876c5-7ca6-4da7-866d-3e7886651411','ملخص كتاب الجيل القلق بقلم جوناثان هايدت','&lt;p&gt;في كتاب &#34;الجيل القلق&#34; يكشف عالم النفس الاجتماعي جوناثان هايدت كيف غيّرت الهواتف الذكية ووسائل التواصل الاجتماعي شكل الطفولة الحديثة، وكيف انتقل الأطفال من عالم اللعب والاستكشاف إلى عالم الشاشات والإشعارات والمقارنات المستمرة.يناقش الكتاب تأثير التكنولوجيا على النوم، والتركيز، والصحة النفسية، والعلاقات الاجتماعية، ويوضح لماذا يحتاج الأطفال إلى مزيد من اللعب الحر والاستقلال في العالم الحقيقي، مع حماية أكبر في العالم الرقمي.&lt;/p&gt;&lt;hr/&gt;&lt;p&gt;Powered by &lt;a href=&#34;h','https://media.podeo.co/episodes/MTIzMjMy/audio.mp3',848,'2026-07-24T07:12:10.000Z'::timestamptz,39631);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('9c3876c5-7ca6-4da7-866d-3e7886651411','ملخص كتاب فرضية السعادة بقلم جوناثان هايدت','&lt;p&gt;هل السعادة تأتي من المال، أم النجاح، أم العلاقات، أم من طريقة تفكيرنا؟في هذا الملخص لكتاب **«فرضية السعادة»** للمؤلف **جوناثان هايدت**، نتعرف على مزيج فريد يجمع بين الحكمة القديمة وأحدث أبحاث علم النفس، ليشرح لماذا لا يكفي أن تعرف ما هو الصحيح، ولماذا تقودنا عواطفنا وعاداتنا أحيانًا في الاتجاه المعاكس لما نريده.&lt;/p&gt;&lt;hr/&gt;&lt;p&gt;Powered by &lt;a href=&#34;https://podeo.co&#34;&gt;Podeo&lt;/a&gt; — &lt;a href=&#34;https://play.podeo.co/episodes/285025160&#34;&gt;Listen to thi','https://media.podeo.co/episodes/MTIyMDU0/audio.mp3',801,'2026-07-10T05:58:13.000Z'::timestamptz,44351);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('9c3876c5-7ca6-4da7-866d-3e7886651411','ملخص كتاب لعبة المكانة بقلم ويل ستور','&lt;p&gt;لماذا نهتم كثيرًا بما يعتقده الآخرون عنا؟ ولماذا نسعى وراء المال، والنجاح، والشهرة، والإعجابات؟في هذا الملخص من كتاب «لعبة المكانة» للمؤلف ويل ستور، نتعرف على واحدة من أقوى الأفكار في علم النفس البشري: أن معظم سلوكياتنا مدفوعة برغبة عميقة في اكتساب المكانة والاحترام والشعور بأن لنا قيمة.يشرح الكتاب كيف تشكل المكانة قراراتنا، وعلاقاتنا، وطموحاتنا، وحتى الطريقة التي نرى بها أنفسنا. كما يكشف لماذا يؤلمنا الرفض، ولماذا تختلف معايير النجاح من مجموعة إلى أخرى، وكيف يمكننا اختيار ألعاب المكانة','https://media.podeo.co/episodes/MTIwMDE3/audio.mp3',706,'2026-06-18T07:12:11.000Z'::timestamptz,32704);
INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('9c3876c5-7ca6-4da7-866d-3e7886651411','ملخص كتاب لغات الحب الخمس بقلم جاري تشابمان','&lt;p&gt;هل شعرت يومًا أنك تعبّر عن الحب بصدق… لكن الطرف الآخر لا يشعر بذلك؟ في هذا الملخص لكتاب «لغات الحب الخمس» لـ، سنتعرّف على الفكرة التي غيّرت طريقة فهم الملايين للعلاقات: الناس لا يشعرون بالحب بالطريقة نفسها. بعضهم يحتاج الكلمات، وآخرون يحتاجون الوقت، أو الاهتمام، أو الأفعال الصغيرة، أو حتى مجرد القرب العاطفي. هذا الملخص يشرح كيف يؤدي سوء التواصل العاطفي إلى المسافة بين الناس، وكيف يمكن لفهم لغة الحب الخاصة بالطرف الآخر أن يقوّي الترابط ويجعل العلاقات أكثر استقرارًا ودفئًا مع الوقت.&lt;/p','https://media.podeo.co/episodes/MTE3MzUy/audio.mp3',783,'2026-05-22T06:06:49.000Z'::timestamptz,50034);

-- كلام سايبر
