INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count) VALUES ('c3dc414f-e483-4593-a36e-23be5b1282c1','كلام سايبر | منتجات سيبرانية واعدة','في هذه الحلقة ننتقل من الحديث مع الشخصيات المهنية إلى تسليط الضوء على ٣ منتجات سيبرانية OTuHunt | GenesisK | Ammen أفكار خرجت من القاعات الدراسية، وتحولت إلى حلول تقنية قابلة للتطبيق، وتطمح لدخول السوق السعودي.💡 الحلقة مفيدة لكل من:- الرياديين المهتمين بتحويل الأفكار السيبرانية إلى منتجات قابلة للتطبيق- الشركات التي ترغب في تطوير حلول R&amp;D - المستثمرين الساعين لدعم منتجات سعودية واعدة- طلاب التخرج الذين يؤمنون أن مشروعهم ليس مجرد درجات، بل بداية رحلة مهنية استمع للحلقة وتعرّف على: ثلاث تقنيا','https://www.buzzsprout.com/2369623/episodes/17604972-.mp3',7008,'2025-08-06T05:00:00.000Z'::timestamptz,15738);

